public:
    long long minimumCost(string s, string t, int flipCost, int swapCost, int crossCost) {
        long long c = 0, d = 0;   // c: (0,1) mismatches, d: (1,0) mismatches
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] == '0' && t[i] == '1') {
                c++;
            } else if (s[i] == '1' && t[i] == '0') {
                d++;
            }
        }

        long long pairs = min(c, d);      // opposite-type pairs
        long long rem = abs(c - d);       // same-type leftovers

        // one swap fixes an opposite pair; otherwise flip both
        long long costPair = min((long long)swapCost, 2LL * flipCost);
        // two same-type leftovers: cross-swap one then swap, or flip both
        long long costDouble = min(2LL * flipCost, (long long)crossCost + swapCost);

        // an odd leftover can only be flipped; long long, totals reach 1e14
        long long ans = pairs * costPair + (rem / 2) * costDouble + (rem % 2) * flipCost;
        return ans;
    }
};

