func nthSmallest(n int64, k int) int64 {
    // Step 1: Pascal's table in int64 (C(50,25) ~ 1.26e14)
    const MAX = 60
    var C [MAX + 1][MAX + 1]int64

    for i := 0; i <= MAX; i++ {
        C[i][0] = 1
        for j := 1; j <= i; j++ {
            C[i][j] = C[i-1][j-1] + C[i-1][j]
        }
    }

    var res int64
    rem := k

    // Step 2: walk bit positions from the top
    for pos := MAX; pos >= 0; pos-- {
        if rem == 0 {
            break
        }
        // C[pos][rem] numbers have a 0 here and rem ones below
        if C[pos][rem] < n {
            // Step 3: rank n is past that block, so this bit is 1
            res |= int64(1) << uint(pos)
            n -= C[pos][rem]
            rem--
        }
    }

    return res
}

