class Solution:
    def longestAlternating(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Step 1: up[i] / down[i] = length of the alternating run ending at i
        # whose last step is up (nums[i-1] < nums[i]) or down (nums[i-1] > nums[i])
        up = [1] * n
        down = [1] * n

        for i in range(1, n):
            if nums[i-1] < nums[i]:
                up[i] = down[i-1] + 1
                down[i] = 1
            elif nums[i-1] > nums[i]:
                down[i] = up[i-1] + 1
                up[i] = 1
            else:
                up[i] = 1
                down[i] = 1

        # Step 2: the same from the right: runs starting at i whose first step is up / down
        start_up = [1] * n
        start_down = [1] * n

        for i in range(n-2, -1, -1):
            if nums[i] < nums[i+1]:
                start_up[i] = start_down[i+1] + 1
                start_down[i] = 1
            elif nums[i] > nums[i+1]:
                start_down[i] = start_up[i+1] + 1
                start_up[i] = 1
            else:
                start_up[i] = 1
                start_down[i] = 1

        # Step 3: best with no removal
        ans = 1
        for i in range(n):
            ans = max(ans, up[i], down[i])

        # Step 4: remove nums[p]; the glued step nums[p-1] -> nums[p+1] must sit between
        # a left run ending in the opposite direction and a right run starting in it
        for p in range(1, n-1):
            if nums[p-1] < nums[p+1]:
                ans = max(ans, down[p-1] + start_down[p+1])
            elif nums[p-1] > nums[p+1]:
                ans = max(ans, up[p-1] + start_up[p+1])

        return ans

