class Solution {
    public int longestAlternating(int[] nums) {
        int n = nums.length;
        // Step 1: up[i] / down[i] = alternating run ending at i whose last step is up / down
        int[] up = new int[n];
        int[] down = new int[n];
        up[0] = 1;
        down[0] = 1;
        int ans = 1;

        for (int i = 1; i < n; i++) {
            if (nums[i] > nums[i-1]) {
                up[i] = down[i-1] + 1;
                down[i] = 1;
            } else if (nums[i] < nums[i-1]) {
                down[i] = up[i-1] + 1;
                up[i] = 1;
            } else {
                up[i] = 1;
                down[i] = 1;
            }
            // Step 2: best with no removal
            ans = Math.max(ans, Math.max(up[i], down[i]));
        }

        // Step 3: runs starting at i whose first step is up / down
        int[] upStart = new int[n];
        int[] downStart = new int[n];
        upStart[n-1] = 1;
        downStart[n-1] = 1;

        for (int i = n-2; i >= 0; i--) {
            if (nums[i] < nums[i+1]) {
                upStart[i] = downStart[i+1] + 1;
                downStart[i] = 1;
            } else if (nums[i] > nums[i+1]) {
                downStart[i] = upStart[i+1] + 1;
                upStart[i] = 1;
            } else {
                upStart[i] = 1;
                downStart[i] = 1;
            }
        }

        // Step 4: remove nums[k]; the glued step must be opposite to the left run's
        // last step and to the right run's first step (equal neighbours never glue)
        for (int k = 1; k < n-1; k++) {
            if (nums[k-1] < nums[k+1]) {
                ans = Math.max(ans, down[k-1] + downStart[k+1]);
            } else if (nums[k-1] > nums[k+1]) {
                ans = Math.max(ans, up[k-1] + upStart[k+1]);
            }
        }

        return ans;
    }
}

