class Solution {
public:
    int longestAlternating(vector<int>& nums) {
        int n = nums.size();
        // Step 1: up[i] / down[i] = alternating run ending at i whose last step is up / down
        vector<int> up(n, 1), down(n, 1);
        for (int i = 1; i < n; ++i) {
            if (nums[i-1] < nums[i]) {
                up[i] = down[i-1] + 1;
            } else if (nums[i-1] > nums[i]) {
                down[i] = up[i-1] + 1;
            }
        }

        // Step 2: runs starting at i whose first step is up / down
        vector<int> rup(n, 1), rdown(n, 1);
        for (int i = n-2; i >= 0; --i) {
            if (nums[i] < nums[i+1]) {
                rup[i] = rdown[i+1] + 1;
            } else if (nums[i] > nums[i+1]) {
                rdown[i] = rup[i+1] + 1;
            }
        }

        // Step 3: prefix / suffix maxima of the no-removal runs
        vector<int> pref(n);
        pref[0] = max(up[0], down[0]);
        for (int i = 1; i < n; ++i) {
            pref[i] = max(pref[i-1], max(up[i], down[i]));
        }

        vector<int> suff(n);
        suff[n-1] = max(rup[n-1], rdown[n-1]);
        for (int i = n-2; i >= 0; --i) {
            suff[i] = max(suff[i+1], max(rup[i], rdown[i]));
        }

        int ans = pref[n-1];

        for (int i = 0; i < n; ++i) {
            // best run that does not use index i
            int best = 0;
            if (i > 0) best = max(best, pref[i-1]);
            if (i < n-1) best = max(best, suff[i+1]);

            // Step 4: remove nums[i]; the glued step must be opposite to the
            // left run's last step and the right run's first step
            if (i > 0 && i < n-1) {
                if (nums[i-1] < nums[i+1]) {
                    best = max(best, down[i-1] + rdown[i+1]);
                } else if (nums[i-1] > nums[i+1]) {
                    best = max(best, up[i-1] + rup[i+1]);
                }
            }
            ans = max(ans, best);
        }

        return ans;
    }
};

