class RideSharingSystem {
    // Two FIFO queues (arrival order) plus the set of riders still waiting.
    private final Queue<Integer> riders;
    private final Queue<Integer> drivers;
    private final Set<Integer> activeRiders;

    public RideSharingSystem() {
        riders = new ArrayDeque<>();
        drivers = new ArrayDeque<>();
