from typing import List

class Solution:
    def minMergeCost(self, lists: List[List[int]]) -> int:
        n = len(lists)
        total_masks = 1 << n

        # Step 1: for every subset of lists, the merged length and the left-middle median.
        # The merged content of a subset does not depend on the merge order, so this is well defined.
        size = [0] * total_masks
        med = [0] * total_masks

        for mask in range(1, total_masks):
            elements = []
            for i in range(n):
                if mask & (1 << i):
                    elements.extend(lists[i])
            elements.sort()
            size[mask] = len(elements)
            med[mask] = elements[(len(elements) - 1) // 2]

        # Step 2: dp[mask] = min cost to merge the subset into one list; a single list costs 0.
        INF = float('inf')
        dp = [INF] * total_masks
        for i in range(n):
            dp[1 << i] = 0

        for mask in range(1, total_masks):
            if bin(mask).count('1') < 2:
                continue
            # Step 3: try every split of mask into two non-empty halves (sub, comp);
            # sub < comp visits each unordered split once.
            sub = (mask - 1) & mask
            while sub > 0:
                comp = mask ^ sub
                if sub < comp:
                    cost = dp[sub] + dp[comp] + size[sub] + size[comp] + abs(med[sub] - med[comp])
                    if cost < dp[mask]:
                        dp[mask] = cost
                sub = (sub - 1) & mask

        return dp[total_masks - 1]

