import java.util.*;

class Solution {
    public long minMergeCost(int[][] lists) {
        int n = lists.length;
        int totalMasks = 1 << n;
        int[] len = new int[totalMasks];
        int[] median = new int[totalMasks];
        int[][] sorted = new int[totalMasks][];

        sorted[0] = new int[0];
        len[0] = 0;

        // Step 1: merged content of every subset, built by adding one list to the subset
        // without its lowest bit (already computed, since prev < mask).
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = mask & -mask;
            int bit = Integer.numberOfTrailingZeros(lsb);
            int prev = mask ^ lsb;
            int[] left = sorted[prev];
            int[] right = lists[bit];
            int[] merged = new int[left.length + right.length];
            int i = 0, j = 0, k = 0;
            while (i < left.length && j < right.length) {
                if (left[i] <= right[j]) {
                    merged[k++] = left[i++];
                } else {
                    merged[k++] = right[j++];
                }
            }
            while (i < left.length) {
                merged[k++] = left[i++];
            }
            while (j < right.length) {
                merged[k++] = right[j++];
            }
            sorted[mask] = merged;
            len[mask] = merged.length;
            median[mask] = merged[(merged.length - 1) / 2];   // left-middle median
        }

        // Step 2: dp[mask] = min cost to merge the subset into one list; single list = 0.
        long[] dp = new long[totalMasks];
        Arrays.fill(dp, Long.MAX_VALUE / 4);

        for (int i = 0; i < n; i++) {
            dp[1 << i] = 0;
        }

        for (int mask = 1; mask < totalMasks; mask++) {
            if ((mask & (mask - 1)) == 0) {
                continue;
            }
            // Step 3: every split into (sub, other); sub < other visits each unordered split once.
            for (int sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
                int other = mask ^ sub;
                if (sub > other) {
                    continue;
                }
                long cost = dp[sub] + dp[other] + (long) len[sub] + len[other]
                          + Math.abs((long) median[sub] - median[other]);
                if (cost < dp[mask]) {
                    dp[mask] = cost;
                }
            }
        }

        return dp[totalMasks - 1];
    }
}

