class Solution {
    public int maximumAND(int[] nums, int k, int m) {
        int n = nums.length;
        int ans = 0;
        // Step 1: decide bits from the top
        for (int bit = 30; bit >= 0; bit--) {
            int candidate = ans | (1 << bit);
            long[] costs = new long[n];
            for (int i = 0; i < n; i++) {
                costs[i] = costToAchieve(nums[i], candidate);
            }
            // Step 3: keep the bit if the m cheapest elements fit in the budget
            Arrays.sort(costs);
            long sum = 0;
            for (int i = 0; i < m; i++) {
                sum += costs[i];
            }
            if (sum <= k) {
                ans = candidate;
            }
        }
        return ans;
    }

    // Step 2: cheapest y >= x whose bits include every bit of T
    private long costToAchieve(int x, int T) {
        if ((x & T) == T) return 0;
        int missing = T & ~x;
        int highest = Integer.highestOneBit(missing);   // highest bit of T that x lacks
        // set that bit, clear everything below it, then copy T's lower bits in
        long y = ((x | highest) & ~(highest - 1)) | (T & (highest - 1));
        return y - x;
    }
}

