import (
	"math/bits"
	"sort"
)

func maximumAND(nums []int, k int, m int) int {
    n := len(nums)
    costs := make([]int, n)
    ans := 0

    // Step 1: decide bits from the top. nums[i] <= 10^9 < 2^30 and k <= 10^9,
    // so values stay below 2^31 and bit 30 is the highest that can matter.
    for b := 30; b >= 0; b-- {
        candidate := ans | (1 << b)

        // Step 2: cheapest val >= num whose bits include every bit of candidate
        for i := 0; i < n; i++ {
            num := nums[i]
            if (num & candidate) == candidate {
                costs[i] = 0
            } else {
                missing := candidate & ^num
                // Most significant bit that is missing (missing > 0 here)
                msb := bits.Len32(uint32(missing)) - 1

                // high_mask keeps bits > msb from num
                high_mask := ^(int64(1)<<(msb+1) - 1)
                val := int64(num) & high_mask
                // Set bit msb to 1
                val |= int64(1) << msb
                // Set required bits < msb from candidate
                val |= int64(candidate) & (int64(1)<<msb - 1)

                costs[i] = int(val - int64(num))
            }
        }

        // Step 3: keep the bit if the m cheapest elements fit in the budget
        sort.Ints(costs)

        sum := int64(0)
        possible := true
        for i := 0; i < m; i++ {
            sum += int64(costs[i])
            if sum > int64(k) {
                possible = false
                break
            }
        }

        if possible {
            ans = candidate
        }
    }

    return ans
}

