import heapq

class AuctionSystem:
    def __init__(self):
        # itemId -> {userId: bidAmount}: the source of truth
        self.bids = {}
        # itemId -> max-heap of (-bidAmount, -userId); may hold stale entries
        self.heaps = {}

    def addBid(self, userId: int, itemId: int, bidAmount: int) -> None:
        if itemId not in self.bids:
            self.bids[itemId] = {}
            self.heaps[itemId] = []
        # overwrite the dict and push a fresh entry; the old heap entry stays and goes stale
        self.bids[itemId][userId] = bidAmount
        heapq.heappush(self.heaps[itemId], (-bidAmount, -userId))

    def updateBid(self, userId: int, itemId: int, newAmount: int) -> None:
        # same as addBid: never search the heap for the old entry
        self.bids[itemId][userId] = newAmount
        heapq.heappush(self.heaps[itemId], (-newAmount, -userId))

    def removeBid(self, userId: int, itemId: int) -> None:
        # dict only; the heap entry is discarded on a later query
        del self.bids[itemId][userId]

    def getHighestBidder(self, itemId: int) -> int:
        if itemId not in self.bids or not self.bids[itemId]:
            return -1
        heap = self.heaps[itemId]
        bids = self.bids[itemId]
        # pop until the top matches the dict in BOTH user and amount
        while heap:
            neg_amount, neg_user = heap[0]
            user = -neg_user
            amount = -neg_amount
            if user in bids and bids[user] == amount:
                return user
            else:
                heapq.heappop(heap)
        return -1

