const compare = (a, b) => {
    // a, b are [amount, userId]; larger amount wins, then larger userId
    if (a[0] !== b[0]) {
        return a[0] - b[0];
    }
    return a[1] - b[1];
};

const heapPush = (heap, val) => {
    heap.push(val);
    let i = heap.length - 1;
    while (i > 0) {
        const parent = Math.floor((i - 1) / 2);
        if (compare(heap[i], heap[parent]) > 0) {
            [heap[i], heap[parent]] = [heap[parent], heap[i]];
            i = parent;
        } else {
            break;
        }
    }
};

const heapPop = (heap) => {
    if (heap.length === 0) return undefined;
    const root = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return root;
    heap[0] = last;
    let i = 0;
    const n = heap.length;
    while (true) {
        const left = 2 * i + 1;
        const right = 2 * i + 2;
        let largest = i;
        if (left < n && compare(heap[left], heap[largest]) > 0) {
            largest = left;
        }
        if (right < n && compare(heap[right], heap[largest]) > 0) {
            largest = right;
        }
        if (largest !== i) {
            [heap[i], heap[largest]] = [heap[largest], heap[i]];
            i = largest;
        } else {
            break;
        }
    }
    return root;
};

