import "container/heap"

type Bid struct {
	amount int
	userId int
}

// max-heap by amount, then by userId, so the root is the answer
type MaxHeap []Bid

func (h MaxHeap) Len() int { return len(h) }
func (h MaxHeap) Less(i, j int) bool {
	if h[i].amount != h[j].amount {
		return h[i].amount > h[j].amount
	}
	return h[i].userId > h[j].userId
}
func (h MaxHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x interface{}) {
	*h = append(*h, x.(Bid))
}

func (h *MaxHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

type AuctionSystem struct {
	bids  map[int]map[int]int // itemId -> userId -> amount: the source of truth
	heaps map[int]*MaxHeap    // itemId -> heap that may hold stale entries
}

func Constructor() AuctionSystem {
	return AuctionSystem{
		bids:  make(map[int]map[int]int),
		heaps: make(map[int]*MaxHeap),
	}
}

func (this *AuctionSystem) AddBid(userId int, itemId int, bidAmount int) {
	if _, ok := this.bids[itemId]; !ok {
		this.bids[itemId] = make(map[int]int)
	}
	this.bids[itemId][userId] = bidAmount

	if _, ok := this.heaps[itemId]; !ok {
		h := make(MaxHeap, 0)
		this.heaps[itemId] = &h
	}
	// push a fresh entry; the old one stays and goes stale
	heap.Push(this.heaps[itemId], Bid{amount: bidAmount, userId: userId})
}

func (this *AuctionSystem) UpdateBid(userId int, itemId int, newAmount int) {
	this.bids[itemId][userId] = newAmount
	heap.Push(this.heaps[itemId], Bid{amount: newAmount, userId: userId})
}

func (this *AuctionSystem) RemoveBid(userId int, itemId int) {
	// map only; the heap entry is discarded on a later query
	delete(this.bids[itemId], userId)
	if len(this.bids[itemId]) == 0 {
		delete(this.bids, itemId)
	}
}

func (this *AuctionSystem) GetHighestBidder(itemId int) int {
	users, ok := this.bids[itemId]
	if !ok || len(users) == 0 {
		return -1
	}

	h := this.heaps[itemId]
	// pop until the root matches the map in both user and amount
	for h.Len() > 0 {
		top := (*h)[0]
		if amt, exists := users[top.userId]; exists && amt == top.amount {
			return top.userId
		}
		heap.Pop(h)
	}

	return -1
}

