class Solution {
    public int almostPalindromic(String s) {
        int n = s.length();
        // dp[i][j] = minimum deletions that make s[i..j] a palindrome
        int[][] dp = new int[n][n];
        // base: length 1
        for (int i = 0; i < n; i++) {
            dp[i][i] = 0;
        }
        // fill by increasing length so dp[i+1][j-1], dp[i+1][j], dp[i][j-1] are ready
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    // matching ends cost nothing
                    dp[i][j] = (i + 1 <= j - 1) ? dp[i + 1][j - 1] : 0;
                } else {
                    // delete one end, whichever leaves the cheaper inside
                    dp[i][j] = 1 + Math.min(dp[i + 1][j], dp[i][j - 1]);
                }
            }
        }
        // almost-palindromic <=> at most one deletion needed
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (dp[i][j] <= 1) {
                    maxLen = Math.max(maxLen, j - i + 1);
                }
            }
        }
        return maxLen;
    }
}

