class Solution {
public:
    int almostPalindromic(string s) {
        int n = s.size();
        // pal[i][j] = 1 if s[i..j] is a palindrome
        vector<vector<char>> pal(n, vector<char>(n, 0));
        for (int i = 0; i < n; ++i) pal[i][i] = 1;
        for (int i = 0; i < n - 1; ++i) {
            pal[i][i+1] = (s[i] == s[i+1]);
        }
        for (int len = 3; len <= n; ++len) {
            for (int i = 0; i + len - 1 < n; ++i) {
                int j = i + len - 1;
                pal[i][j] = (s[i] == s[j] && pal[i+1][j-1]);
            }
        }
        // almost[i][j] = 1 if s[i..j] is a palindrome after deleting one char
        vector<vector<char>> almost(n, vector<char>(n, 0));
        int ans = 1;
        for (int i = 0; i < n; ++i) {
            almost[i][i] = 1;
        }
        // every length-2 substring qualifies
        for (int i = 0; i < n - 1; ++i) {
            almost[i][i+1] = 1;
            ans = max(ans, 2);
        }
        for (int len = 3; len <= n; ++len) {
            for (int i = 0; i + len - 1 < n; ++i) {
                int j = i + len - 1;
                if (s[i] == s[j]) {
                    // equal ends: the deletion happens strictly inside
                    almost[i][j] = almost[i+1][j-1];
                } else {
                    // unequal ends: one of them must be the deleted char
                    almost[i][j] = pal[i+1][j] || pal[i][j-1];
                }
                if (almost[i][j]) ans = max(ans, len);
            }
        }
        return ans;
    }
};

