func almostPalindromic(s string) int {
	n := len(s)
	if n < 2 {
		return 0
	}

	// isPal[l][r]: s[l..r] is a palindrome
	isPal := make([][]bool, n)
	for i := 0; i < n; i++ {
		isPal[i] = make([]bool, n)
		isPal[i][i] = true
	}
	for len := 2; len <= n; len++ {
		for l := 0; l+len-1 < n; l++ {
			r := l + len - 1
			if s[l] == s[r] && (len == 2 || isPal[l+1][r-1]) {
				isPal[l][r] = true
			}
		}
	}

	// dp[l][r]: s[l..r] becomes a palindrome after deleting exactly one char
	dp := make([][]bool, n)
	for i := 0; i < n; i++ {
		dp[i] = make([]bool, n)
	}
	maxLen := 2
	// every length-2 substring qualifies
	for i := 0; i < n-1; i++ {
		dp[i][i+1] = true
	}

	// lengths from 3 to n
	for length := 3; length <= n; length++ {
		for l := 0; l+length-1 < n; l++ {
			r := l + length - 1
			if isPal[l][r] {
				dp[l][r] = true // already a palindrome
			} else if isPal[l+1][r] {
				dp[l][r] = true // delete s[l]
			} else if isPal[l][r-1] {
				dp[l][r] = true // delete s[r]
			} else if s[l] == s[r] && dp[l+1][r-1] {
				dp[l][r] = true // equal ends, deletion strictly inside
			}
			if dp[l][r] && length > maxLen {
				maxLen = length
			}
		}
	}
	return maxLen
}
